mapper.sql:
where certificate.del_flag = '0' and certificate.approval_instance_id is null and certificate.review_status in ('PENDING_REVIEW', 'APPROVED', 'REJECTED')
and cast(certificate.certificate_id as char) = #{query.businessId}
and case certificate.review_status when 'PENDING_REVIEW' then 'RUNNING' else certificate.review_status end = upper(#{query.status})
